import sys
from itertools import product

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    edges = []
    for _ in range(m):
        a = int(next(it)) - 1
        b = int(next(it)) - 1
        edges.append((a, b))

    # Precompute all domino types (a,b) with 1<=a<=b<=6
    dominos = []
    for a in range(1, 7):
        for b in range(a, 7):
            dominos.append((a, b))
    D = len(dominos)  # 21

    # Precompute for each edge and each orientation (0/1) which domino indices fit
    # orientation 0: dots[u] = x, dots[v] = y
    # orientation 1: dots[u] = y, dots[v] = x
    edge_dom = [[[], []] for _ in range(m)]
    for e_idx, (u, v) in enumerate(edges):
        for d_idx, (a, b) in enumerate(dominos):
            edge_dom[e_idx][0].append((d_idx, a, b))
            edge_dom[e_idx][1].append((d_idx, b, a))

    best = 0

    # For each assignment of vertex labels (0..6) where 0 means unused, 1..6 dots
    # n<=7 so 7^7 = 823543 possibilities
    for labels in product(range(7), repeat=n):
        # Quick upper bound: count vertices with non-zero labels
        # Each such vertex can be incident to at most 6 edges (since labels 1..6)
        # but we skip complex pruning, rely on later matching.
        # Build list of candidate edges that can be used under this labeling
        cand_edges = []
        for e_idx, (u, v) in enumerate(edges):
            lu = labels[u]
            lv = labels[v]
            if lu == 0 or lv == 0:
                continue
            cand_edges.append((e_idx, u, v, lu, lv))
        if not cand_edges:
            continue

        # For each candidate edge, build list of domino indices that match labels
        edge_options = []
        for e_idx, u, v, lu, lv in cand_edges:
            opts = []
            for d_idx, a, b in dominos:
                if (a == lu and b == lv) or (a == lv and b == lu):
                    opts.append(d_idx)
            if not opts:
                continue
            edge_options.append((e_idx, opts))
        if not edge_options:
            continue

        # Maximum bipartite matching: edges (left) to dominos (right)
        # Left size <= m (<=21), right size = 21
        L = len(edge_options)
        adj = [[] for _ in range(L)]
        for i, (_, opts) in enumerate(edge_options):
            adj[i] = opts

        matchR = [-1] * D

        def dfs(u, seen):
            for d in adj[u]:
                if seen[d]:
                    continue
                seen[d] = True
                if matchR[d] == -1 or dfs(matchR[d], seen):
                    matchR[d] = u
                    return True
            return False

        match_size = 0
        for u in range(L):
            seen = [False] * D
            if dfs(u, seen):
                match_size += 1

        if match_size > best:
            best = match_size

    print(best)

if __name__ == "__main__":
    main()
